// ============================================================
// Extrai o JSON da análise da IA (de forma robusta) e monta o
// relatório HTML final + texto de alerta para o Slack
// ============================================================
const raw = $input.first().json;
let text = raw.text ?? raw.output ?? raw.response ?? '';
if (typeof text !== 'string') text = JSON.stringify(text);

let analysis = null;
try { analysis = JSON.parse(text); } catch (e) {
  const fence = text.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (fence) { try { analysis = JSON.parse(fence[1]); } catch (e2) {} }
  if (!analysis) {
    const m = text.match(/\{[\s\S]*\}/);
    if (m) { try { analysis = JSON.parse(m[0]); } catch (e3) {} }
  }
}
if (!analysis) analysis = {
  resumo_executivo: { nota_geral: null, nivel_urgencia: 'media', sintese: text.slice(0, 1200) || 'Análise indisponível nesta execução.' },
  diagnostico: [], quick_wins: [], hipoteses_ab: [], investigar_no_clarity: [], plano_30_dias: []
};

const data = $('Comparar Tendências').first().json;
const ov = data.overview || {};
const fr = ov.frictionRates || {};

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fmt = n => (n === null || n === undefined) ? '—' : Number(n).toLocaleString('pt-BR');
const pct = n => (n === null || n === undefined) ? '—' : Number(n).toLocaleString('pt-BR') + '%';
const mmss = s => (s === null || s === undefined) ? '—' : Math.floor(s / 60) + 'm ' + Math.round(s % 60) + 's';

function trendArrow(v, invert) {
  if (v === null || v === undefined) return '';
  const good = invert ? v < 0 : v > 0;
  const color = v === 0 ? '#6b7280' : good ? '#059669' : '#dc2626';
  const arrow = v > 0 ? '▲' : v < 0 ? '▼' : '＝';
  return `<span style="color:${color};font-size:11px;font-weight:700"> ${arrow} ${Math.abs(v).toLocaleString('pt-BR')}%</span>`;
}
function scoreColor(s) { return s >= 25 ? '#dc2626' : s >= 15 ? '#ea580c' : s >= 8 ? '#d97706' : '#059669'; }
function sevBadge(sev) {
  const s = String(sev || 'media').toLowerCase();
  const map = { critica: '#dc2626', alta: '#ea580c', media: '#d97706', baixa: '#059669' };
  const c = map[s.normalize('NFD').replace(/[̀-ͯ]/g, '')] || '#d97706';
  return `<span style="background:${c}1a;color:${c};font-size:10px;font-weight:700;padding:2px 8px;border-radius:12px;text-transform:uppercase">${esc(sev)}</span>`;
}

const kpi = (label, value, extra) =>
  `<td style="padding:12px 14px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;text-align:center;min-width:100px">
     <div style="font-size:11px;color:#64748b;margin-bottom:4px">${esc(label)}</div>
     <div style="font-size:20px;font-weight:800;color:#0f172a">${value}${extra || ''}</div>
   </td>`;

function frictionRow(r) {
  const f = r.friction || {};
  const p = k => f[k]?.pct !== undefined ? pct(f[k].pct) : '—';
  return `<tr>
    <td style="padding:8px;border-bottom:1px solid #e2e8f0;font-size:12px;word-break:break-all;max-width:280px">${esc(r.dimension)}</td>
    <td style="padding:8px;border-bottom:1px solid #e2e8f0;text-align:right;font-size:12px">${fmt(r.sessions)}</td>
    <td style="padding:8px;border-bottom:1px solid #e2e8f0;text-align:center"><span style="font-weight:800;color:${scoreColor(r.frictionScore)}">${fmt(r.frictionScore)}</span></td>
    <td style="padding:8px;border-bottom:1px solid #e2e8f0;text-align:center;font-size:12px">${p('rageClicks')}</td>
    <td style="padding:8px;border-bottom:1px solid #e2e8f0;text-align:center;font-size:12px">${p('deadClicks')}</td>
    <td style="padding:8px;border-bottom:1px solid #e2e8f0;text-align:center;font-size:12px">${p('quickbacks')}</td>
    <td style="padding:8px;border-bottom:1px solid #e2e8f0;text-align:center;font-size:12px">${r.scrollDepth !== null ? pct(r.scrollDepth) : '—'}</td>
  </tr>`;
}
function frictionTable(title, rows) {
  if (!rows?.length) return '';
  return `<h3 style="font-size:15px;color:#0f172a;margin:28px 0 10px">${esc(title)}</h3>
  <div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-family:inherit">
    <tr style="background:#f1f5f9">
      <th style="padding:8px;text-align:left;font-size:11px;color:#475569">Dimensão</th>
      <th style="padding:8px;text-align:right;font-size:11px;color:#475569">Sessões</th>
      <th style="padding:8px;text-align:center;font-size:11px;color:#475569">Score Fricção</th>
      <th style="padding:8px;text-align:center;font-size:11px;color:#475569">Rage %</th>
      <th style="padding:8px;text-align:center;font-size:11px;color:#475569">Dead %</th>
      <th style="padding:8px;text-align:center;font-size:11px;color:#475569">Quickback %</th>
      <th style="padding:8px;text-align:center;font-size:11px;color:#475569">Scroll médio</th>
    </tr>${rows.map(frictionRow).join('')}
  </table></div>`;
}

const t = data.trends || {};
const re = analysis.resumo_executivo || {};

const diagHtml = (analysis.diagnostico || []).map(d => `
  <div style="border-left:3px solid #94a3b8;background:#f8fafc;border-radius:0 8px 8px 0;padding:12px 14px;margin-bottom:8px">
    <div style="margin-bottom:4px">${sevBadge(d.severidade)} <strong style="font-size:13px">${esc(d.area)}</strong></div>
    <div style="font-size:13px;color:#334155">${esc(d.achado)}</div>
    <div style="font-size:12px;color:#64748b;margin-top:4px">📊 ${esc(d.evidencia)}</div>
    ${d.causa_provavel ? `<div style="font-size:12px;color:#64748b;margin-top:2px">💡 Causa provável: ${esc(d.causa_provavel)}</div>` : ''}
  </div>`).join('');

const qwHtml = (analysis.quick_wins || []).map((q, i) => `
  <div style="display:flex;gap:10px;background:#f0fdf4;border:1px solid #bbf7d0;border-radius:8px;padding:10px 12px;margin-bottom:6px">
    <div style="min-width:22px;height:22px;background:#059669;color:#fff;border-radius:50%;text-align:center;font-size:12px;font-weight:700;line-height:22px">${i + 1}</div>
    <div style="font-size:13px;color:#14532d"><strong>${esc(q.acao)}</strong><br>
      <span style="color:#166534">${esc(q.motivo)}</span>
      <span style="color:#64748b;font-size:12px"> · ${esc(q.pagina_alvo || '')} · ⏱ ${esc(q.prazo || '')}</span></div>
  </div>`).join('');

const abHtml = (analysis.hipoteses_ab || []).map(h => `
  <div style="border:1px solid #e2e8f0;border-radius:8px;padding:12px 14px;margin-bottom:8px">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px">
      <strong style="font-size:13px;word-break:break-all">${esc(h.pagina)}</strong>
      <span style="background:#eef2ff;color:#4338ca;font-size:11px;font-weight:800;padding:2px 10px;border-radius:12px">ICE ${esc(h.ice_score)}</span>
    </div>
    <div style="font-size:13px;color:#334155">${esc(h.hipotese)}</div>
    <div style="font-size:12px;color:#64748b;margin-top:4px">🧪 ${esc(h.variante_proposta)} · 🎯 ${esc(h.metrica_primaria)} · I:${esc(h.impact)} C:${esc(h.confidence)} E:${esc(h.ease)}</div>
  </div>`).join('');

const invHtml = (analysis.investigar_no_clarity || []).map(v => `
  <div style="background:#fefce8;border:1px solid #fde68a;border-radius:8px;padding:10px 12px;margin-bottom:6px;font-size:13px;color:#713f12">
    <strong>${esc(v.ferramenta)}:</strong> ${esc(v.o_que)}<br>
    <span style="font-size:12px;color:#854d0e">🔎 Filtro: ${esc(v.filtro_sugerido)}<br>❓ ${esc(v.pergunta_a_responder)}</span>
  </div>`).join('');

const planHtml = (analysis.plano_30_dias || []).map(w => `
  <tr>
    <td style="padding:8px;border-bottom:1px solid #e2e8f0;font-weight:700;font-size:12px;white-space:nowrap">Semana ${esc(w.semana)}</td>
    <td style="padding:8px;border-bottom:1px solid #e2e8f0;font-size:12px">${esc(w.foco)}</td>
    <td style="padding:8px;border-bottom:1px solid #e2e8f0;font-size:12px">${(w.acoes || []).map(esc).join('<br>• ')}</td>
  </tr>`).join('');

const alertsHtml = (data.alerts || []).length ? `
  <div style="background:#fef2f2;border:1px solid #fecaca;border-radius:8px;padding:12px 14px;margin:16px 0">
    <strong style="color:#dc2626;font-size:13px">🚨 ${data.alerts.length} página(s) acima do limite de fricção</strong>
    <ul style="margin:6px 0 0 18px;font-size:12px;color:#7f1d1d">
      ${data.alerts.map(a => `<li style="word-break:break-all">${esc(a.url)} — score ${a.frictionScore} (${fmt(a.sessions)} sessões)</li>`).join('')}
    </ul>
  </div>` : '';

const gsColor = scoreColor(ov.frustrationScore ?? 0);
const html = `<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Auditoria CRO/UX – ${esc(data.projectName)}</title></head>
<body style="margin:0;background:#f1f5f9;font-family:'Segoe UI',Arial,sans-serif;color:#0f172a">
<div style="max-width:860px;margin:0 auto;padding:24px 16px">
  <div style="background:linear-gradient(135deg,#1e3a8a,#3b82f6);border-radius:12px;padding:22px 26px;color:#fff">
    <h1 style="margin:0;font-size:20px">🔬 Auditoria CRO/UX — Microsoft Clarity</h1>
    <p style="margin:6px 0 0;font-size:13px;opacity:.85">${esc(data.projectName)} · últimos ${esc(data.periodDays)} dia(s) · gerado em ${new Date(data.generatedAt).toLocaleString('pt-BR')}${t.comparadoCom ? ' · comparado com ' + esc(t.comparadoCom) : ''}</p>
  </div>

  <div style="background:#fff;border-radius:12px;padding:22px 26px;margin-top:14px">
