return [{ json: {
  snapshotDate: data.snapshotDate,
  projectName: data.projectName,
  frustrationScore: ov.frustrationScore ?? 0,
  alert,
  slackText,
  html,
  analysis,
  metrics: {
    generatedAt: data.generatedAt, snapshotDate: data.snapshotDate, periodDays: data.periodDays,
    overview: ov, byUrl: data.byUrl, byDevice: data.byDevice, bySource: data.bySource,
    byTech: data.byTech, alerts: data.alerts, apiStatus: data.apiStatus, trends: data.trends
  }
}}];

// Seleciona o relatório mais recente (ou por ?date=YYYY-MM-DD)
const q = $('GET – Relatório CRO').first().json.query ?? {};
const rows = $input.all().map(i => i.json).filter(r => r && r.report);
rows.sort((a, b) => String(b.snapshotDate).localeCompare(String(a.snapshotDate)));
const row = q.date ? rows.find(r => String(r.snapshotDate) === String(q.date)) : rows[0];
const html = row ? row.report :
  '<!DOCTYPE html><html lang="pt-BR"><body style="font-family:sans-serif;padding:48px;color:#334155">' +
  '<h2>Nenhum relatório disponível ainda</h2><p>Execute o workflow de auditoria primeiro. ' +
  'Você também pode acessar um dia específico com <code>?date=YYYY-MM-DD</code>.</p></body></html>';
return [{ json: { html } }];
